def find_max_prime_factors(target, min_prime_factors, max_prime_factors):
    if target == 0:
        return 0

    if target < min_prime_factors:
        return -1

    max_count = 0

    for prime_factors in range(min_prime_factors, max_prime_factors + 1):
        if prime_factors <= target:
            remaining_target = target - prime_factors
            count = find_max_prime_factors(remaining_target, min_prime_factors, prime_factors - 1)

            if count != -1:
                max_count = max(max_count, count + 1)

    return max_count


def generate(seed):
    rng = random.Random(seed)

    min_prime_factors = rng.randint(2, 10)
    max_prime_factors = rng.randint(15, 25)
    target_value = rng.randint(20, 50)

    answer = find_max_prime_factors(target_value, min_prime_factors, max_prime_factors)

    check = -1
    for prime_factors in range(min_prime_factors, max_prime_factors + 1):
        if prime_factors <= target_value:
            remaining_target = target_value - prime_factors
            count = find_max_prime_factors(remaining_target, min_prime_factors, prime_factors - 1)
            if count != -1:
                check = max(check, 1 + count)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider a sequence of integers where the sum of any subset of prime factors ranges from {min_prime_factors} to {max_prime_factors} (inclusive). "
        f"What is the maximum number of distinct prime factors that can be selected such that no subset sum exceeds the target prime factors {target_value} and all subset sums sum to exactly {target_value}? State only the integer."
    )
    return problem, str(answer)

