def count_rectangles(m, n, min_area, max_area):
    rectangles = [0] * (max_area + 1)
    rectangles[0] = 1

    for k in range(min_area, max_area + 1):
        for i in range(m, k // min(m, n) + 1):
            for j in range(n, k // min(m, n) + 1):
                if i * j <= k:
                    rectangles[k] += rectangles[k - (i * j)]

    return rectangles[max_area]

def generate(seed):
    rng = random.Random(seed)

    m = rng.randint(2, 5)
    n = rng.randint(2, 5)
    min_area = rng.randint(m * n, 10 * m * n)
    max_area = rng.randint(min_area, 20 * m * n)
    threshold_count = 0

    # Find the threshold number of rectangles
    for i in range(min_area, max_area + 1):
        if count_rectangles(m, n, min_area, i) > 0:
            threshold_count = i
            break

    # Independent route: iterate from the minimum area count to find the smallest area that can form a valid combination.
    for i in range(min_area, max_area + 1):
        if count_rectangles(m, n, min_area, i) > 0:
            check_threshold_count = i
            break

    assert threshold_count == check_threshold_count, f"threshold_count={threshold_count} check_threshold_count={check_threshold_count}"

    problem = (
        f"Determine the smallest area of rectangles with dimensions up to {m}x{n} (inclusive) such that a set of {threshold_count} rectangles can be formed with each rectangle having an area between {min_area} and {threshold_count} (inclusive) where all areas sum to exactly {threshold_count}. State only the integer."
    )
